script:
// Matematikai inga – pontos megoldás és kis kitérésű közelítés
// Simple pendulum – exact motion vs. small-angle approximation
//   θ'' = −(g/L)·sin θ − c·θ'        T₀ = 2π·√(L/g)

// Vászon: szélesség, magasság (px), háttérszín / Canvas: width, height (px), background colour
stage(1000, 600, "#f8f9fb");
// Felirat a vászon bal felső sarkában / Caption in the top-left corner
title({hu: "Matematikai inga", en: "Simple pendulum"});

// Csúszkák: azonosító, felirat (HU/EN), min, max, alapérték, lépés, egység – értékük: P.azonosító / Sliders: id, label (HU/EN), min, max, default, step, unit – value: P.id
param("L",   {hu: "Fonálhossz L", en: "Length L"}, 0.2, 3, 1.5, 0.05, "m");
param("th0", {hu: "Kezdeti kitérés θ₀", en: "Initial angle θ₀"}, 5, 170, 30, 1, "°");
param("g",   {hu: "Nehézségi gyorsulás g", en: "Gravity g"}, 1, 25, 9.81, 0.01, "m/s²");
param("c",   {hu: "Csillapítás c", en: "Damping c"}, 0, 1, 0, 0.01, "1/s");
// Kapcsolók: értékük true / false / Switches: their value is true / false
toggle("ghost", {hu: "Kis kitérésű közelítés (szürke)", en: "Small-angle approximation (grey)"}, true);
toggle("vec",   {hu: "Erővektorok", en: "Force vectors"}, true);
// Ezek változásakor a jelenet újraindul / The scene restarts when these change
resetOn("L", "th0");

let th = deg(P.th0), w = 0, lastCross = null, Tm = null, prev = th;

// Fizika: sok kis lépésben fut, dt a lépés hossza (s) / Physics: runs in many small steps, dt is the step length (s)
update((dt, t) => {
  // Mozgásegyenlet: θ'' = −(g/L)·sin θ − c·θ' / equation of motion
  w += (-P.g / P.L * sin(th) - P.c * w) * dt;
  th += w * dt;
  // Nullátmenet → mért lengésidő / zero crossing → measured period
  if (prev < 0 && th >= 0) { if (lastCross !== null) Tm = t - lastCross; lastCross = t; }
  prev = th;
});

// Rajzolás minden képkockán (szünetben is) / Drawing on every frame (also while paused)
draw(t => {
  const px = 500, py = 70, sc = 150;   // felfüggesztés, px/m / pivot, px per metre
  rect(px - 90, py - 16, 180, 16, {fill: "#d7dde6"});
  for (let x = px - 86; x < px + 90; x += 12) line(x, py - 16, x + 8, py - 26, {stroke: C.gray, lw: 1});
  line(px, py, px, py + P.L * sc + 40, {stroke: C.gray, lw: 1, dash: [4, 6]});

  // Közelítés: θ₀·cos(√(g/L)·t) – kis kitérésre pontos / approximation, exact for small angles
  if (P.ghost) {
    const tg = deg(P.th0) * cos(sqrt(P.g / P.L) * t) * exp(-P.c * t / 2);
    const gx = px + P.L * sc * sin(tg), gy = py + P.L * sc * cos(tg);
    line(px, py, gx, gy, {stroke: C.gray, lw: 1.5, alpha: 0.5});
    circle(gx, gy, 20, {fill: C.gray, alpha: 0.35, stroke: false});
  }

  const bx = px + P.L * sc * sin(th), by = py + P.L * sc * cos(th);
  line(px, py, bx, by, {stroke: C.ink, lw: 2});
  arc(px, py, 56, PI / 2 - max(th, 0), PI / 2 - min(th, 0), {stroke: C.ink, lw: 1.2});
  circle(px, py, 5, {fill: C.ink});
  circle(bx, by, 20, {fill: C.blue, stroke: "#173b8f", lw: 1.5});

  if (P.vec) {
    const F = 90;   // mg = 90 px
    vector(bx, by, 0, F, {stroke: C.red, lw: 3}, "mg");
    const ft = -sin(th) * F;   // visszatérítő összetevő / restoring component
    vector(bx, by, cos(th) * ft, -sin(th) * ft, {stroke: C.orange, lw: 2.5}, "mg·sin θ");
    vector(bx, by, cos(th) * w * 30, -sin(th) * w * 30, {stroke: C.green, lw: 2}, "v");
  }

  const T0 = 2 * PI * sqrt(P.L / P.g);
  // Mért értékek a Vezérlők fülön / Readouts on the Controls tab
  show({hu: "Kitérés θ", en: "Angle θ"}, todeg(th), "°");
  show({hu: "Szögsebesség ω", en: "Angular velocity ω"}, w, "rad/s");
  show({hu: "Lengésidő T₀ = 2π√(L/g)", en: "Period T₀ = 2π√(L/g)"}, T0, "s");
  show({hu: "Mért lengésidő", en: "Measured period"}, Tm === null ? "…" : Tm, "s");
  show({hu: "Sebesség v = L·ω", en: "Speed v = L·ω"}, abs(P.L * w), "m/s");

  // Élő grafikonok a vászon alatt / Live charts under the canvas
  plot({hu: "Kitérés θ", en: "Angle θ"}, todeg(th), {unit: "°", color: C.blue});
  plot({hu: "Szögsebesség ω", en: "Angular velocity ω"}, w, {unit: "rad/s", color: C.green});
});
